admin_access_assert_capability($pdo,$admin,'admin.customer_success.view');$canManage=admin_access_has_capability($pdo,$admin,'admin.customer_success.manage');$id=trim((string)($_GET['id']??$_POST['id']??''));$account=$id!==''?account_admin_get($pdo,$id):null;if(!$account){http_response_code(404);exit('Account not found.');}$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{if(!$canManage)throw new RuntimeException('Your operator role cannot manage Customer Success.');$op=(string)($_POST['op']??'');
