    elseif(in_array($op,['followup_complete','followup_cancel','followup_reopen'],true)){admin_customer_success_followup_update($pdo,$admin,(string)($_POST['followup_id']??''),substr($op,9),(string)($_POST['reason']??''));$success='Follow-up updated.';}
