    elseif(in_array($op,['plan_pause','plan_resume','plan_complete','plan_cancel'],true)){admin_customer_success_plan_update($pdo,$admin,(string)($_POST['plan_id']??''),substr($op,5),(string)($_POST['reason']??''));$success='Success plan updated.';}
    elseif($op==='milestone_create'){admin_customer_success_milestone_create($pdo,$admin,(string)($_POST['plan_id']??''),$_POST);$success='Milestone added.';}
    elseif($op==='milestone_status'){admin_customer_success_milestone_update($pdo,$admin,(string)($_POST['milestone_id']??''),(string)($_POST['status']??''),(string)($_POST['reason']??''));$success='Milestone updated.';}
    else throw new RuntimeException('Unknown Customer Success action.');
}catch(Throwable $e){$error=$e->getMessage();}}
$data=admin_customer_success_account($pdo,$admin,(int)$account['id']);$health=$data['current_health'];$snapshot=$data['latest_snapshot'];$assignment=$data['assignment'];$plans=$data['plans'];$followups=$data['followups'];$events=$data['events'];$history=$data['health_history'];$support=$data['support'];$finance=$data['finance'];$members=$data['members'];$usage=$data['usage'];$operators=admin_customer_success_operator_candidates($pdo);$stateLabel=fn(string $s)=>ucwords(str_replace('_',' ',$s));$stale=$snapshot===null||!hash_equals((string)$snapshot['fingerprint'],(string)$health['fingerprint']);
